select month(last_restock) as last_restock_month, case when quantity >= 265 then 'high' when quantity >= 106 then 'mid' else 'low' end as quantity_bucket, store_id, count(quantity) as quantity_count, min(last_restock) as min_last_restock from inventory where last_restock between '2025-06-13' and '2025-10-01' and (last_restock <= '2025-08-01' or quantity <= 109) group by 1, 2, 3 having quantity_count < 1 order by quantity_count desc;
